'use strict';

/**
 * Represents a WhatsApp data structure
 */
class Base {
    constructor(client) {
        /**
         * The client that instantiated this
         * @readonly
         */
        Object.defineProperty(this, 'client', { value: client });
    }

    _clone() {
        return Object.assign(Object.create(this), this);
    }
    
    _patch(data) { return data; }

    /**
     * Normalizes a WhatsApp ID object so that `_serialized` is always defined.
     * WhatsApp Web renamed `_serialized` to `$1` in July 2026; copying it back
     * keeps every downstream `id._serialized` read working.
     * Ported from upstream wwebjs/whatsapp-web.js@58ddf15.
     * @param {object} id
     * @returns {object}
     */
    static _normalizeId(id) {
        if (id && id._serialized == null && id.$1 != null) {
            return Object.assign({}, id, { _serialized: id.$1 });
        }
        return id;
    }
}

module.exports = Base;